import axios from "axios";
import React, { useEffect, useState } from "react";
import { useParams, useNavigate, Link } from "react-router-dom";
import {
  FiArrowLeft,
  FiFileText,
  FiEye,
  FiClock,
  FiMapPin,
  FiUser,
  FiPhone,
  FiMail,
  FiExternalLink,
  FiX,
  FiCheckCircle,
  FiXCircle,
  FiTruck,
  FiDollarSign,
  FiPackage,
  FiAlertCircle,
  FiCheck,
  FiShoppingBag
} from "react-icons/fi";

const UserRequestQuotationsDetails = () => {
  const { id, buyerId: routeBuyerId, requestId } = useParams();
  const navigate = useNavigate();

  const [loading, setLoading] = useState(true);
  const [requestData, setRequestData] = useState(null);
  const [quotations, setQuotations] = useState([]);
  const [error, setError] = useState(null);

  const resolvedBuyerId =
    id ||
    routeBuyerId ||
    (typeof requestData?.buyerId === "object" ? requestData?.buyerId?._id : requestData?.buyerId);

  const handleBack = () => {
    if (resolvedBuyerId) {
      navigate(`/userBooking/${resolvedBuyerId}?tab=requests`, { state: { tab: "requests" } });
    } else {
      navigate(-1);
    }
  };

  // Modal State
  const [showQuotationModal, setShowQuotationModal] = useState(false);
  const [selectedQuotation, setSelectedQuotation] = useState(null);

  const fetchRequestQuotations = async () => {
    if (!requestId) return;
    try {
      setLoading(true);
      setError(null);
      const res = await axios.get(
        `${process.env.REACT_APP_BACKEND_URL}/api/productRequest/admin/request/${requestId}/quotations`
      );
      if (res.data.success) {
        setRequestData(res.data.request);
        setQuotations(res.data.quotations || []);
      } else {
        setError(res.data.message || "Failed to load quotations");
      }
    } catch (err) {
      console.error("Error fetching request quotations:", err);
      setError("Error loading quotation data. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRequestQuotations();
  }, [requestId]);

  // Prevent background scrolling when modal is open
  useEffect(() => {
    if (showQuotationModal) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "auto";
    }
    return () => {
      document.body.style.overflow = "auto";
    };
  }, [showQuotationModal]);

  const formatDate = (dateVal) => {
    if (!dateVal) return "N/A";
    const d = new Date(dateVal);
    return d.toLocaleString("en-IN", {
      day: "2-digit",
      month: "short",
      year: "numeric",
      hour: "2-digit",
      minute: "2-digit",
      hour12: true,
    });
  };

  const getRequestStatusBadge = (status) => {
    switch (status) {
      case "EXPIRED":
        return <span className="badge bg-danger px-2.5 py-1.5 fs-12">Expired</span>;
      case "PENDING":
      case "OPEN":
      case "SUBMITTED":
        return <span className="badge bg-warning text-dark px-2.5 py-1.5 fs-12">Pending</span>;
      case "CONFIRMED":
      case "PROCESSING":
      case "COMPLETED":
        return <span className="badge bg-success px-2.5 py-1.5 fs-12">{status}</span>;
      default:
        return <span className="badge bg-secondary px-2.5 py-1.5 fs-12">{status || "Pending"}</span>;
    }
  };

  return (
    <div className="dashboard-body__content">
      {/* Top Back Button (Outside Card) */}
      <div className="mb-3">
        <button
          type="button"
          className="btn btn-sm d-inline-flex align-items-center gap-2 rounded-pill px-3.5 py-2 text-white border-0 shadow-sm"
          style={{
            backgroundColor: "#715DF2",
            fontWeight: "600",
            fontSize: "13.5px",
            cursor: "pointer",
            transition: "all 0.2s ease",
          }}
          onClick={handleBack}
          title="Return to Buyer Requests"
        >
          <FiArrowLeft size={16} />
          <span>Back to Buyer Requests</span>
        </button>
      </div>

      {/* Top Header Card */}
      <div className="card common-card border border-gray-five mb-4" style={{ borderRadius: "12px", overflow: "hidden" }}>
        <div className="card-body p-3 p-md-4">
          <div className="d-flex flex-wrap align-items-center justify-content-between gap-3">
            <div>
              <h4 style={{ margin: 0, fontSize: "19px", fontWeight: "700", color: "#1e293b" }}>
                Product Request Quotations
              </h4>
              <p style={{ margin: "2px 0 0 0", fontSize: "13px", color: "#64748b" }}>
                Review seller quotations, product details, and manage pricing for this buyer request
              </p>
            </div>

            {requestData && (
              <div className="d-flex flex-wrap align-items-center gap-2">
                <span className="badge bg-light text-dark border px-2.5 py-1.5 fs-12 fw-semibold">
                  Request: <strong style={{ color: "#715DF2" }}>#{requestData.orderId || requestId?.slice(-8)}</strong>
                </span>
                {getRequestStatusBadge(requestData.status)}
              </div>
            )}
          </div>
        </div>
      </div>

      {loading ? (
        <div className="text-center py-5">
          <div className="spinner-border text-primary" role="status">
            <span className="visually-hidden">Loading...</span>
          </div>
          <p className="mt-2 text-muted">Loading request and quotations...</p>
        </div>
      ) : error ? (
        <div className="alert alert-danger p-4 text-center rounded-3">
          <h5>Unable to load data</h5>
          <p className="mb-3">{error}</p>
          <button
            type="button"
            className="btn btn-primary btn-sm rounded-pill px-4"
            onClick={fetchRequestQuotations}
          >
            Retry
          </button>
        </div>
      ) : (
        <>
          {/* User Details & Delivery Address Card (Single Full-Width Card with generous padding) */}
          {requestData && (() => {
            const userName =
              requestData.deliveryAddress?.name ||
              requestData.buyerId?.name ||
              requestData.buyerId?.basicInformation?.fullName ||
              "Buyer";

            const userPhone =
              requestData.deliveryAddress?.phone ||
              requestData.deliveryAddress?.mobile ||
              requestData.buyerId?.mobile ||
              "N/A";

            const userEmail =
              requestData.deliveryAddress?.email ||
              requestData.buyerId?.email ||
              "N/A";

            const addressParts = [
              requestData.deliveryAddress?.houseNo,
              requestData.deliveryAddress?.addressLine || requestData.deliveryAddress?.address,
              requestData.deliveryAddress?.landmark ? `Near ${requestData.deliveryAddress.landmark}` : "",
              requestData.deliveryAddress?.city,
              requestData.deliveryAddress?.state,
              requestData.deliveryAddress?.pincode ? `- ${requestData.deliveryAddress.pincode}` : ""
            ].filter(Boolean);

            const fullAddress = addressParts.length > 0
              ? addressParts.join(", ")
              : (requestData.deliveryAddress?.address || "Address not provided");

            const mapLink =
              requestData.deliveryAddress?.googleMapLocationLink ||
              requestData.deliveryAddress?.googleMapLink ||
              requestData.deliveryAddress?.googleMap ||
              (requestData.deliveryAddress?.latitude && requestData.deliveryAddress?.longitude
                ? `https://www.google.com/maps?q=${requestData.deliveryAddress.latitude},${requestData.deliveryAddress.longitude}`
                : `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(fullAddress)}`);

            return (
              <div className="card common-card border border-gray-five mb-4" style={{ borderRadius: "12px", overflow: "hidden" }}>
                <div className="p-4 border-bottom bg-light d-flex flex-wrap align-items-center justify-content-between gap-3">
                  <div className="d-flex align-items-center gap-2">
                    <FiUser className="text-primary" size={20} />
                    <h5 className="m-0 fw-bold text-dark" style={{ fontSize: "17px" }}>
                      User Details &amp; Delivery Address
                    </h5>
                  </div>
                  <div className="d-flex align-items-center gap-3">
                    <span className="text-muted fs-13">
                      Request ID: <strong style={{ color: "#715DF2" }}>#{requestData?.orderId || requestId?.slice(-8)}</strong>
                    </span>
                    <span className="text-muted fs-13">
                      Created on <strong>{formatDate(requestData.createdAt)}</strong>
                    </span>
                  </div>
                </div>

                <div className="card-body p-4 p-md-4">
                  <div className="row g-4">
                    {/* User Name, Phone, Email */}
                    <div className="col-lg-4 col-md-5">
                      <div className="p-4 rounded-3 border bg-white h-100 shadow-sm d-flex flex-column justify-content-between gap-3">
                        <div>
                          <div className="text-muted fs-11 fw-700 text-uppercase d-flex align-items-center gap-1.5 mb-1.5">
                            <FiUser className="text-primary" size={14} /> Customer Name
                          </div>
                          <div className="fs-16 fw-bold text-dark">{userName}</div>
                        </div>

                        <div>
                          <div className="text-muted fs-11 fw-700 text-uppercase d-flex align-items-center gap-1.5 mb-1.5">
                            <FiPhone className="text-primary" size={14} /> Phone Number
                          </div>
                          <div className="fs-15 fw-600 text-dark">
                            {userPhone !== "N/A" ? (
                              <a href={`tel:${userPhone}`} className="text-decoration-none text-dark">
                                {userPhone}
                              </a>
                            ) : (
                              "N/A"
                            )}
                          </div>
                        </div>

                        <div>
                          <div className="text-muted fs-11 fw-700 text-uppercase d-flex align-items-center gap-1.5 mb-1.5">
                            <FiMail className="text-primary" size={14} /> Email Address
                          </div>
                          <div className="fs-14 text-dark text-break">
                            {userEmail !== "N/A" ? (
                              <a href={`mailto:${userEmail}`} className="text-decoration-none" style={{ color: "#715DF2", fontWeight: "600" }}>
                                {userEmail}
                              </a>
                            ) : (
                              "N/A"
                            )}
                          </div>
                        </div>
                      </div>
                    </div>

                    {/* Delivery Address & Google Maps button */}
                    <div className="col-lg-8 col-md-7">
                      <div className="p-4 rounded-3 border bg-white h-100 shadow-sm d-flex flex-column justify-content-between gap-3">
                        <div>
                          <div className="d-flex align-items-center justify-content-between mb-2">
                            <div className="text-muted fs-11 fw-700 text-uppercase d-flex align-items-center gap-1.5">
                              <FiMapPin className="text-primary" size={14} /> Registered Delivery Address
                            </div>
                            {requestData.deliveryAddress?.landmark && (
                              <span className="badge bg-light text-muted border fs-12 px-2.5 py-1">
                                Landmark: {requestData.deliveryAddress.landmark}
                              </span>
                            )}
                          </div>
                          <div className="fs-14 text-dark" style={{ lineHeight: "1.7", fontWeight: "500" }}>
                            {fullAddress}
                          </div>
                        </div>

                        <div className="pt-3 border-top d-flex flex-wrap align-items-center justify-content-between gap-2">
                          <span className="text-muted fs-13">
                            📍 View location on Google Maps
                          </span>
                          <a
                            href={mapLink}
                            target="_blank"
                            rel="noreferrer"
                            className="btn btn-sm btn-primary d-inline-flex align-items-center gap-1.5 px-4 py-2 rounded-pill shadow-sm"
                            style={{
                              backgroundColor: "#715DF2",
                              borderColor: "#715DF2",
                              fontSize: "13px",
                              fontWeight: "600",
                            }}
                            title="Open location in Google Maps"
                          >
                            <FiMapPin size={14} />
                            <span>Google Maps Location</span>
                            <FiExternalLink size={13} className="ms-0.5" />
                          </a>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            );
          })()}

          {/* Quotations Table Section */}
          <div className="card common-card border border-gray-five" style={{ borderRadius: "12px" }}>
            <div className="p-4 border-bottom d-flex flex-wrap align-items-center justify-content-between gap-3">
              <div>
                <h4 style={{ margin: 0, fontWeight: "700", color: "#1e293b" }}>
                  All Received Quotations ({quotations.length})
                </h4>
                <p style={{ margin: "2px 0 0 0", fontSize: "13px", color: "#64748b" }}>
                  Detailed breakdown of pricing and medicine availability submitted by sellers
                </p>
              </div>
              <span className="badge bg-primary px-3 py-2 fs-12" style={{ backgroundColor: "#715DF2" }}>
                {quotations.length} Quotation{quotations.length !== 1 ? "s" : ""} Total
              </span>
            </div>

            <div className="card-body p-0">
              {quotations.length === 0 ? (
                <div className="text-center py-5 text-muted">
                  <FiAlertCircle size={40} className="mb-2 text-warning" />
                  <h5>No Quotations Received Yet</h5>
                  <p className="fs-14">There are currently no seller quotations for this request.</p>
                </div>
              ) : (
                <div className="table-responsive">
                  <table className="table text-body table-hover align-middle mb-0 custom-admin-table">
                    <thead style={{ backgroundColor: "#f8fafc", color: "#334155" }}>
                      <tr>
                        <th className="ps-4" style={{ width: "50px" }}>#</th>
                        <th>Quotation ID</th>
                        <th>Seller / Pharmacy</th>
                        <th>Submitted Date</th>
                        <th>Items Quoted</th>
                        <th>Delivery Mode</th>
                        <th>Total Quoted Price</th>
                        <th className="text-center pe-4" style={{ width: "120px" }}>Action</th>
                      </tr>
                    </thead>
                    <tbody>
                      {quotations.map((quote, qIdx) => {
                        const sellerName =
                          quote.sellerId?.basicInformation?.shopName ||
                          quote.sellerId?.basicInformation?.contactPersonName ||
                          quote.sellerName ||
                          "Seller";

                        const sellerPhone =
                          quote.sellerId?.contactInformation?.Mobileprimary ||
                          quote.sellerPhone ||
                          "";

                        const quoteTotal = Number(quote.totalPrice || quote.finalPrice || 0);
                        const itemsCount = quote.items?.length || 0;

                        return (
                          <tr key={quote._id || qIdx}>
                            <td className="ps-4 fw-bold text-muted">{qIdx + 1}</td>
                            <td>
                              <strong style={{ color: "#715DF2" }}>
                                {quote.quotationId || quote._id?.slice(-8)}
                              </strong>
                            </td>
                            <td>
                              <div className="fw-600 text-dark">{sellerName}</div>
                              {sellerPhone && (
                                <div className="text-muted font-11">📞 {sellerPhone}</div>
                              )}
                            </td>
                            <td className="text-muted fs-13">
                              {formatDate(quote.createdAt)}
                            </td>
                            <td>
                              <span className="badge bg-light text-dark border fs-12">
                                {itemsCount} item{itemsCount !== 1 ? "s" : ""}
                              </span>
                            </td>
                            <td>
                              <span className="text-muted fs-13">
                                {quote.deliveryOption?.replace(/_/g, " ") || "Home Delivery"}
                              </span>
                              {quote.estimatedDeliveryTime && (
                                <div className="text-muted font-11">⏱️ {quote.estimatedDeliveryTime}</div>
                              )}
                            </td>
                            <td>
                              <strong className="text-dark fs-15">₹{quoteTotal.toLocaleString("en-IN")}</strong>
                            </td>
                            <td className="text-center pe-4">
                              <button
                                type="button"
                                className="btn btn-sm btn-primary d-inline-flex align-items-center gap-1.5 px-3 py-1.5 rounded-pill shadow-sm"
                                style={{
                                  backgroundColor: "#715DF2",
                                  borderColor: "#715DF2",
                                  fontSize: "13px",
                                  fontWeight: "600",
                                }}
                                onClick={() => {
                                  setSelectedQuotation(quote);
                                  setShowQuotationModal(true);
                                }}
                                title="View Complete Quotation Details"
                              >
                                <FiEye size={14} />
                              </button>
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          </div>
        </>
      )}

      {/* ========================= MODAL: QUOTATION DETAILS =========================== */}
      {showQuotationModal && selectedQuotation && (() => {
        const isPrescriptionType =
          requestData?.requestType?.toLowerCase() === "prescription" ||
          (!requestData?.items || requestData?.items.length === 0) ||
          (requestData?.prescriptionUrls && requestData?.prescriptionUrls.length > 0 && (!requestData?.items || requestData?.items.length === 0));

        const bName =
          requestData?.deliveryAddress?.name ||
          requestData?.buyerId?.name ||
          requestData?.buyerId?.basicInformation?.fullName ||
          "Customer";

        const bPhone =
          requestData?.deliveryAddress?.phone ||
          requestData?.deliveryAddress?.mobile ||
          requestData?.buyerId?.mobile ||
          "N/A";

        const bEmail =
          requestData?.deliveryAddress?.email ||
          requestData?.buyerId?.email ||
          "N/A";

        const addressParts = [
          requestData?.deliveryAddress?.houseNo,
          requestData?.deliveryAddress?.addressLine || requestData?.deliveryAddress?.address,
          requestData?.deliveryAddress?.landmark ? `Near ${requestData?.deliveryAddress.landmark}` : "",
          requestData?.deliveryAddress?.city,
          requestData?.deliveryAddress?.state,
          requestData?.deliveryAddress?.pincode ? `- ${requestData?.deliveryAddress.pincode}` : ""
        ].filter(Boolean);

        const bFullAddress = addressParts.length > 0
          ? addressParts.join(", ")
          : (requestData?.deliveryAddress?.address || "Address not provided");

        const sBasic = selectedQuotation.sellerId?.basicInformation;
        const sContact = selectedQuotation.sellerId?.contactInformation;
        const shopName = sBasic?.shopName || selectedQuotation.sellerName || "N/A";
        const contactPerson = sBasic?.contactPersonName || "";
        const sPhone = sContact?.Mobileprimary || selectedQuotation.sellerPhone || "N/A";
        const sEmail = sContact?.Emailprimary || "N/A";

        const sellerAddressParts = [
          sBasic?.houseNo,
          sBasic?.addressLine1,
          sBasic?.addressLine2,
          sBasic?.landmark ? `Near ${sBasic.landmark}` : "",
          sBasic?.city,
          sBasic?.state,
          sBasic?.pincode ? `- ${sBasic.pincode}` : ""
        ].filter(Boolean);

        const sellerFullAddress = sellerAddressParts.length > 0
          ? sellerAddressParts.join(", ")
          : "Address on file";

        const sellerMapLink =
          sBasic?.googleMapLocationLink ||
          sBasic?.googleMapLink ||
          sBasic?.googleMap ||
          `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(sellerFullAddress)}`;

        return (
          <div
            style={{
              position: "fixed",
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              backgroundColor: "rgba(15, 23, 42, 0.65)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              zIndex: 1050,
              padding: "15px",
              backdropFilter: "blur(4px)",
            }}
            onClick={() => setShowQuotationModal(false)}
          >
            <div
              style={{
                backgroundColor: "#ffffff",
                borderRadius: "14px",
                maxWidth: "1020px",
                width: "100%",
                boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.25)",
                position: "relative",
                overflow: "hidden",
                maxHeight: "92vh",
                display: "flex",
                flexDirection: "column",
              }}
              onClick={(e) => e.stopPropagation()}
            >
              <div className="d-flex align-items-center justify-content-between px-4 py-3.5 border-bottom bg-white sticky-top" style={{ zIndex: 10 }}>
                <div>
                  <h4 className="m-0 fw-bold text-dark d-flex align-items-center" style={{ fontSize: "19px", gap: "6px" }}>
                    <span>Details:</span>
                    <span style={{ color: "#715DF2" }}>#{requestData?.orderId || requestId?.slice(-8)}</span>
                  </h4>
                  <div className="text-muted fs-12 mt-1 fw-500">
                    Date: <strong>{formatDate(requestData?.createdAt)}</strong>
                    <span className="mx-2 text-muted">|</span>
                    Type: <strong className="text-uppercase" style={{ color: "#334155" }}>{isPrescriptionType ? "PRESCRIPTION" : "PRODUCT"}</strong>
                  </div>
                </div>
                <button
                  type="button"
                  onClick={() => setShowQuotationModal(false)}
                  style={{
                    width: "36px",
                    height: "36px",
                    borderRadius: "50%",
                    backgroundColor: "#F1F5F9",
                    border: "1px solid #CBD5E1",
                    color: "#0F172A",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    padding: 0,
                    cursor: "pointer",
                    flexShrink: 0,
                    outline: "none",
                    boxShadow: "0 1px 2px rgba(0,0,0,0.05)",
                    transition: "all 0.15s ease",
                  }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.backgroundColor = "#E2E8F0";
                    e.currentTarget.style.borderColor = "#94A3B8";
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.backgroundColor = "#F1F5F9";
                    e.currentTarget.style.borderColor = "#CBD5E1";
                  }}
                  title="Close modal"
                  aria-label="Close modal"
                >
                  <FiX size={19} color="#0F172A" strokeWidth={2.5} style={{ display: "block" }} />
                </button>
              </div>

              <div className="p-4" style={{ overflowY: "auto" }}>
                <div
                  className="p-3.5 p-md-4 mb-4 rounded-3 bg-white shadow-xs border"
                  style={{ borderColor: "#E2E8F0" }}
                >
                  <div className="d-flex flex-wrap align-items-center justify-content-between gap-2 mb-3.5 border-bottom pb-3">
                    <h6 className="fw-bold text-dark m-0 fs-15 d-flex align-items-center" style={{ gap: "8px" }}>
                      <FiPackage style={{ color: "#715DF2", flexShrink: 0 }} size={18} />
                      <span>Seller Details &amp; Quotation Overview</span>
                    </h6>
                  </div>

                  <div className="row g-4 align-items-center">
                    <div className="col-md-7">
                      <div className="row g-3">
                        <div className="col-sm-6">
                          <div
                            className="text-muted fs-11 fw-700 text-uppercase d-flex align-items-center mb-1.5"
                            style={{ gap: "7px" }}
                          >
                            <FiShoppingBag style={{ color: "#715DF2", flexShrink: 0 }} size={14} />
                            <span>Pharmacy Name</span>
                          </div>
                          <div className="fw-bold text-dark fs-14 ps-1">{shopName}</div>
                        </div>

                        {contactPerson && (
                          <div className="col-sm-6">
                            <div
                              className="text-muted fs-11 fw-700 text-uppercase d-flex align-items-center mb-1.5"
                              style={{ gap: "7px" }}
                            >
                              <FiUser style={{ color: "#715DF2", flexShrink: 0 }} size={14} />
                              <span>Contact Person</span>
                            </div>
                            <div className="fw-semibold text-dark fs-13.5 ps-1">{contactPerson}</div>
                          </div>
                        )}

                        <div className="col-sm-6">
                          <div
                            className="text-muted fs-11 fw-700 text-uppercase d-flex align-items-center mb-1.5"
                            style={{ gap: "7px" }}
                          >
                            <FiPhone style={{ color: "#715DF2", flexShrink: 0 }} size={14} />
                            <span>Phone Number</span>
                          </div>
                          <div className="fw-semibold text-dark fs-13.5 ps-1">
                            {sPhone !== "N/A" ? (
                              <a href={`tel:${sPhone}`} className="text-decoration-none text-dark hover-primary">
                                {sPhone}
                              </a>
                            ) : (
                              <span className="text-muted">N/A</span>
                            )}
                          </div>
                        </div>

                        <div className="col-sm-6">
                          <div
                            className="text-muted fs-11 fw-700 text-uppercase d-flex align-items-center mb-1.5"
                            style={{ gap: "7px" }}
                          >
                            <FiMail style={{ color: "#715DF2", flexShrink: 0 }} size={14} />
                            <span>Email Address</span>
                          </div>
                          <div className="fw-semibold text-dark fs-13.5 text-break ps-1">{sEmail}</div>
                        </div>

                        <div className="col-12 mt-2">
                          <div
                            className="text-muted fs-11 fw-700 text-uppercase d-flex align-items-center mb-1.5"
                            style={{ gap: "7px" }}
                          >
                            <FiMapPin style={{ color: "#715DF2", flexShrink: 0 }} size={14} />
                            <span>Pharmacy Address</span>
                          </div>
                          <div className="text-dark fs-13.5 ps-1" style={{ lineHeight: "1.65", color: "#334155" }}>
                            {sellerFullAddress}
                          </div>
                        </div>
                      </div>
                    </div>

                    <div className="col-md-5">
                      <div
                        className="rounded-3 bg-light border d-flex flex-column gap-3 text-md-end"
                        style={{ padding: "18px 20px" }}
                      >
                        <div>
                          <div
                            className="text-muted fs-11 fw-700 text-uppercase d-flex align-items-center justify-content-md-end mb-1.5"
                            style={{ gap: "7px" }}
                          >
                            <FiTruck style={{ color: "#715DF2", flexShrink: 0 }} size={15} />
                            <span>Delivery Option</span>
                          </div>
                          <span className="fw-bold text-dark fs-14 d-inline-block">
                            {selectedQuotation.deliveryOption?.replace(/_/g, " ") || "Home Delivery"}
                            {selectedQuotation.estimatedDeliveryTime && (
                              <span className="text-muted fs-12 ms-1 fw-normal">
                                (⏱️ {selectedQuotation.estimatedDeliveryTime})
                              </span>
                            )}
                          </span>
                        </div>

                        <div className="pt-2.5 border-top">
                          <div className="text-muted fs-11 fw-700 text-uppercase mb-1">
                            Total Quoted Price
                          </div>
                          <span className="fs-22 fw-bold" style={{ color: "#715DF2" }}>
                            ₹{Number(selectedQuotation.totalPrice || selectedQuotation.finalPrice || 0).toLocaleString("en-IN")}
                          </span>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>

                {/* For Prescription Requests: Show overall prescription status card */}
                {isPrescriptionType && (() => {
                  const quoteRxStatus = selectedQuotation.prescriptionStatus || (
                    Array.isArray(selectedQuotation.prescriptionReviews) && selectedQuotation.prescriptionReviews.some(r => r.status === "Not OK")
                      ? "Not OK"
                      : (Array.isArray(selectedQuotation.prescriptionReviews) && selectedQuotation.prescriptionReviews.length > 0 ? "OK" : "OK")
                  );
                  const isOverallNotOk = quoteRxStatus === "Not OK" || quoteRxStatus === "Rejected";
                  const rxRejectionReason = selectedQuotation.prescriptionRejectionReason || (
                    Array.isArray(selectedQuotation.prescriptionReviews)
                      ? selectedQuotation.prescriptionReviews.filter(r => r.status === "Not OK").map(r => r.rejectionReason).filter(Boolean).join("; ")
                      : ""
                  );

                  const rxUrls = [];
                  if (Array.isArray(selectedQuotation.prescriptionDetails)) {
                    selectedQuotation.prescriptionDetails.forEach(d => {
                      if (d?.prescriptionUrl && !rxUrls.includes(d.prescriptionUrl)) rxUrls.push(d.prescriptionUrl);
                    });
                  }
                  if (Array.isArray(selectedQuotation.prescriptionReviews)) {
                    selectedQuotation.prescriptionReviews.forEach(r => {
                      if (r?.prescriptionUrl && !rxUrls.includes(r.prescriptionUrl)) rxUrls.push(r.prescriptionUrl);
                    });
                  }
                  if (rxUrls.length === 0 && Array.isArray(requestData?.prescriptionUrls)) {
                    requestData.prescriptionUrls.forEach(u => {
                      if (u && !rxUrls.includes(u)) rxUrls.push(u);
                    });
                  }

                  return (
                    <div
                      className="p-3.5 mb-4 rounded-3 border"
                      style={{
                        backgroundColor: isOverallNotOk ? "#FEF2F2" : "#F0FDF4",
                        borderColor: isOverallNotOk ? "#FECACA" : "#BBF7D0"
                      }}
                    >
                      <div className="d-flex flex-wrap align-items-center justify-content-between gap-2">
                        <div>
                          <div className="d-flex align-items-center gap-2">
                            <span
                              className="badge rounded-pill px-3 py-1.5 fs-12 fw-bold text-white d-inline-flex align-items-center gap-1.5"
                              style={{ backgroundColor: isOverallNotOk ? "#DC2626" : "#15803D" }}
                            >
                              {isOverallNotOk ? <FiXCircle size={13} /> : <FiCheckCircle size={13} />}
                              Overall Prescription Status: {isOverallNotOk ? "Not OK (Rejected)" : "OK (Approved)"}
                            </span>
                          </div>
                          {isOverallNotOk && rxRejectionReason && (
                            <div className="mt-2 text-danger fs-13 fw-600">
                              <strong>Rejection Reason:</strong> {rxRejectionReason}
                            </div>
                          )}
                        </div>

                        {rxUrls.length > 0 && (
                          <div className="d-flex flex-wrap gap-2">
                            {rxUrls.map((url, uIdx) => {
                              const baseURL = process.env.REACT_APP_BACKEND_URL;
                              const fullUrl = url.startsWith('http') ? url : (baseURL ? `${baseURL}/${url}` : url);
                              const fileName = url.split('/').pop() || `Prescription_${uIdx + 1}.pdf`;
                              return (
                                <a
                                  key={uIdx}
                                  href={fullUrl}
                                  target="_blank"
                                  rel="noopener noreferrer"
                                  className="btn btn-sm d-inline-flex align-items-center gap-1.5 shadow-xs"
                                  style={{
                                    backgroundColor: "#715DF2",
                                    color: "#ffffff",
                                    border: "1px solid #715DF2",
                                    borderRadius: "6px",
                                    fontSize: "12px",
                                    padding: "6px 12px",
                                    fontWeight: "600",
                                    textDecoration: "none"
                                  }}
                                >
                                  <FiFileText size={13} />
                                  <span>View Prescription</span>
                                  <FiExternalLink size={11} />
                                </a>
                              );
                            })}
                          </div>
                        )}
                      </div>
                    </div>
                  );
                })()}

                <div className="mb-2.5 d-flex align-items-center justify-content-between">
                  <h6 className="fw-bold fs-15 text-dark m-0 d-flex align-items-center" style={{ gap: "8px" }}>
                    <FiPackage style={{ color: "#715DF2", flexShrink: 0 }} size={17} />
                    <span>Items ({selectedQuotation.items?.length || 0})</span>
                  </h6>
                </div>

                <div className="table-responsive rounded-3 mb-3" style={{ overflowX: "auto" }}>
                  <table
                    className="table align-middle mb-0 custom-admin-table"
                    style={{ minWidth: isPrescriptionType ? "780px" : "960px", width: "100%", tableLayout: "fixed" }}
                  >
                    <thead style={{ backgroundColor: "#F8FAFC", color: "#1e293b", fontSize: "12.5px", fontWeight: "700" }}>
                      <tr>
                        <th className="ps-3 text-center" style={{ width: "45px", whiteSpace: "nowrap" }}>#</th>
                        <th style={{ width: isPrescriptionType ? "380px" : "320px", whiteSpace: "nowrap" }}>Product Name &amp; Details</th>
                        {!isPrescriptionType && (
                          <th className="text-center" style={{ width: "190px", whiteSpace: "nowrap" }}>Prescription</th>
                        )}
                        <th className="text-center" style={{ width: "85px", whiteSpace: "nowrap" }}>Quantity</th>
                        <th className="text-center" style={{ width: "105px", whiteSpace: "nowrap" }}>MRP (₹)</th>
                        <th className="text-center" style={{ width: "95px", whiteSpace: "nowrap" }}>Discount</th>
                        <th className="text-end pe-3" style={{ width: "120px", whiteSpace: "nowrap" }}>Final Price</th>
                      </tr>
                    </thead>
                    <tbody style={{ fontSize: "13px" }}>
                      {selectedQuotation.items && selectedQuotation.items.length > 0 ? (
                        selectedQuotation.items.map((item, iIdx) => {
                          const isAvailable =
                            item.available === "Yes" ||
                            item.isAvailable === "Yes" ||
                            item.availableStatus === "Yes" ||
                            item.available === true;

                          // 1. Extract prescription rejection reason if any
                          const rxRejectionReason =
                            item.prescriptionRejectionReason ||
                            item.rejectionReason ||
                            (Array.isArray(item.prescriptionDetails)
                              ? item.prescriptionDetails.find((d) => d.rejectionReason && d.rejectionReason.trim())?.rejectionReason
                              : null);

                          // 2. Determine if prescription is rejected (Not Okay)
                          const isRxNotOK = !isPrescriptionType && Boolean(
                            item.prescriptionStatus === "Not OK" ||
                            item.prescriptionStatus === "Not Okay" ||
                            item.prescriptionStatus === "Rejected" ||
                            item.prescriptionReviewStatus === "Not OK" ||
                            item.prescriptionReviewStatus === "Not Okay" ||
                            (Array.isArray(item.prescriptionDetails) &&
                              item.prescriptionDetails.some(
                                (d) => d.status === "Not OK" || d.status === "Not Okay" || d.status === "Rejected"
                              )) ||
                            (rxRejectionReason && rxRejectionReason.trim())
                          );

                          // 3. Determine if prescription is approved (Okay) - only if NOT rejected
                          const isRxOK =
                            !isPrescriptionType &&
                            !isRxNotOK &&
                            Boolean(
                              item.prescriptionStatus === "OK" ||
                              item.prescriptionStatus === "Okay" ||
                              item.prescriptionStatus === "Approved" ||
                              item.prescriptionReviewStatus === "OK" ||
                              item.prescriptionReviewStatus === "Okay" ||
                              (Array.isArray(item.prescriptionDetails) &&
                                item.prescriptionDetails.length > 0 &&
                                item.prescriptionDetails.every((d) => d.status === "OK" || d.status === "Okay"))
                            );

                          const itemRxUrls = [];
                          if (Array.isArray(item.prescriptionDetails)) {
                            item.prescriptionDetails.forEach((d) => {
                              if (d?.prescriptionUrl && !itemRxUrls.includes(d.prescriptionUrl)) {
                                itemRxUrls.push(d.prescriptionUrl);
                              }
                            });
                          }
                          if (item.prescriptionUrl && !itemRxUrls.includes(item.prescriptionUrl)) {
                            itemRxUrls.push(item.prescriptionUrl);
                          }
                          if (Array.isArray(item.prescriptionUrls)) {
                            item.prescriptionUrls.forEach((u) => {
                              if (u && !itemRxUrls.includes(u)) itemRxUrls.push(u);
                            });
                          }
                          if (itemRxUrls.length === 0 && Array.isArray(requestData?.prescriptionUrls) && requestData.prescriptionUrls.length > 0) {
                            requestData.prescriptionUrls.forEach((u) => {
                              if (u && !itemRxUrls.includes(u)) itemRxUrls.push(u);
                            });
                          }

                          const getPrescriptionFileName = (url) => {
                            if (!url || typeof url !== "string") return "Prescription.pdf";
                            try {
                              const clean = url.split("?")[0].split("#")[0];
                              const name = clean.substring(clean.lastIndexOf("/") + 1);
                              return decodeURIComponent(name) || "Prescription.pdf";
                            } catch {
                              return "Prescription.pdf";
                            }
                          };

                          const itemQty = Number(item.quantity ?? item.requestedQuantity ?? item.qty ?? item.count ?? 1);
                          const unitMrp = Number(item.mrp ?? item.unitMrp ?? item.price ?? item.unitPrice ?? item.finalPrice ?? 0);
                          const itemDiscount = Number(item.discount ?? item.discountAmount ?? item.discountPercent ?? 0);
                          const isPercentDiscount = item.discountType === "Percentage" || Boolean(item.discountPercent);

                          const unitFinal = Number(item.finalPrice ?? item.price ?? (unitMrp > 0 ? unitMrp - itemDiscount : 0));
                          const subtotal = unitFinal * itemQty;

                          return (
                            <tr key={iIdx} style={{ backgroundColor: !isAvailable || isRxNotOK ? "#FFF8F8" : "transparent" }}>
                              <td className="ps-3 text-center fw-bold text-muted" style={{ verticalAlign: "middle" }}>
                                {iIdx + 1}
                              </td>

                              <td style={{ verticalAlign: "middle", padding: "12px 14px", wordBreak: "break-word" }}>
                                <div className="d-flex flex-wrap align-items-center gap-2 mb-1">
                                  <span className="fw-bold text-dark fs-14">{item.productName}</span>

                                  <span
                                    className="badge rounded-pill border px-2.5 py-1 fs-11 fw-bold d-inline-flex align-items-center gap-1"
                                    style={{
                                      backgroundColor: isAvailable ? "#F0FDF4" : "#FEF2F2",
                                      color: isAvailable ? "#16A34A" : "#DC2626",
                                      borderColor: isAvailable ? "#BBF7D0" : "#FECACA",
                                    }}
                                  >
                                    Available: {isAvailable ? "Yes" : "No"}
                                  </span>

                                  {!isPrescriptionType && isRxOK ? (
                                    <span
                                      className="badge rounded-pill px-2.5 py-1 fs-11 fw-bold text-white d-inline-flex align-items-center gap-1"
                                      style={{ backgroundColor: "#15803D" }}
                                    >
                                      <FiCheckCircle size={11} /> Okay
                                    </span>
                                  ) : !isPrescriptionType && isRxNotOK ? (
                                    <span
                                      className="badge rounded-pill px-2.5 py-1 fs-11 fw-bold text-white d-inline-flex align-items-center gap-1"
                                      style={{ backgroundColor: "#DC2626" }}
                                    >
                                      <FiXCircle size={11} /> Not Okay
                                    </span>
                                  ) : null}
                                </div>

                                {item.composition && (
                                  <div className="text-muted font-11">{item.composition}</div>
                                )}
                                {item.brand && Array.isArray(item.brand) && item.brand.length > 0 && (
                                  <div className="text-muted font-11">Brand: {item.brand.join(", ")}</div>
                                )}

                                {!isPrescriptionType && isRxNotOK && (
                                  <div
                                    className="mt-2 p-2 rounded-2"
                                    style={{
                                      backgroundColor: "#FFF1F2",
                                      border: "1px solid #FDA4AF",
                                      fontSize: "11.5px",
                                      maxWidth: "100%",
                                    }}
                                  >
                                    <strong className="text-danger d-block">
                                      ⚠️ Reason: <span className="text-dark fw-500">{rxRejectionReason || "Prescription verification rejected by seller"}</span>
                                    </strong>
                                  </div>
                                )}
                              </td>

                              {!isPrescriptionType && (
                                <td className="text-center" style={{ verticalAlign: "middle", padding: "10px", wordBreak: "break-all" }}>
                                  {itemRxUrls.length > 0 ? (
                                    <div className="d-flex flex-column gap-1.5 align-items-center">
                                      {itemRxUrls.map((u, uIdx) => {
                                        const fileName = getPrescriptionFileName(u);
                                        return (
                                          <a
                                            key={uIdx}
                                            href={u}
                                            target="_blank"
                                            rel="noreferrer"
                                            className="d-inline-flex align-items-center gap-1.5 text-decoration-none"
                                            style={{
                                              color: "#715DF2",
                                              fontSize: "12px",
                                              fontWeight: "600",
                                              maxWidth: "100%",
                                              lineHeight: "1.3",
                                              border: "none",
                                              background: "transparent",
                                            }}
                                            title={`View ${fileName}`}
                                          >
                                            <FiFileText size={13} className="flex-shrink-0" />
                                            <span className="text-truncate" style={{ maxWidth: "160px" }}>
                                              {fileName}
                                            </span>
                                            <FiExternalLink size={11} className="flex-shrink-0" />
                                          </a>
                                        );
                                      })}
                                    </div>
                                  ) : (
                                    <span className="text-muted fs-12 fw-500">
                                      No Prescription
                                    </span>
                                  )}
                                </td>
                              )}

                              <td className="text-center fw-bold text-dark fs-14" style={{ verticalAlign: "middle", whiteSpace: "nowrap" }}>
                                {itemQty}
                              </td>

                              <td className="text-center fw-semibold text-dark fs-13" style={{ verticalAlign: "middle", whiteSpace: "nowrap" }}>
                                ₹{unitMrp.toLocaleString("en-IN")}
                              </td>

                              <td className="text-center" style={{ verticalAlign: "middle", whiteSpace: "nowrap" }}>
                                {itemDiscount > 0 ? (
                                  <span className="text-success font-13 fw-bold">
                                    {isPercentDiscount ? `${itemDiscount}%` : `₹${itemDiscount}`}
                                  </span>
                                ) : (
                                  <span className="text-muted font-13">0%</span>
                                )}
                              </td>

                              <td className="text-end pe-3" style={{ verticalAlign: "middle", whiteSpace: "nowrap" }}>
                                <strong className="text-dark fs-14">₹{subtotal.toLocaleString("en-IN")}</strong>
                                {itemQty > 1 && (
                                  <div className="text-muted font-11">(₹{unitFinal.toLocaleString("en-IN")}/unit)</div>
                                )}
                              </td>
                            </tr>
                          );
                        })
                      ) : (
                        <tr>
                          <td colSpan={isPrescriptionType ? "6" : "7"} className="text-center text-muted py-3">
                            No item level breakdown available in this quotation.
                          </td>
                        </tr>
                      )}
                    </tbody>
                    {selectedQuotation.items && selectedQuotation.items.length > 0 && (
                      <tfoot style={{ backgroundColor: "#F8FAFC", borderTop: "2px solid #E2E8F0" }}>
                        <tr>
                          <td colSpan={isPrescriptionType ? "5" : "6"} className="text-end fw-bold text-dark ps-3 py-2.5 fs-13">
                            Total Amount:
                          </td>
                          <td className="text-end pe-3 fw-bold fs-15 py-2.5" style={{ color: "#715DF2" }}>
                            ₹{Number(selectedQuotation.totalPrice || selectedQuotation.finalPrice || 0).toLocaleString("en-IN")}
                          </td>
                        </tr>
                      </tfoot>
                    )}
                  </table>
                </div>
              </div>

              <div className="p-3 border-top bg-light text-end">
                <button
                  type="button"
                  className="btn btn-secondary btn-sm px-4 rounded-pill"
                  onClick={() => setShowQuotationModal(false)}
                >
                  Close
                </button>
              </div>
            </div>
          </div>
        );
      })()}
    </div>
  );
};

export default UserRequestQuotationsDetails;
